            new Quote { Id = "https://ru.wikiquote.org/wiki/Максим_Горький", Text = "Если кактусы отвлекли вас от резьбы из дерева - да будут прокляты и сгниют! Дрянь кактусы. Иван Соловей-Ракицкий развёл их в саду кучу, всех сортов, шипы и колючки вонзаются в брюки мои...", Author = "Максим Горький" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Максим_Горький", Text = "Против нас всё, что отжило свои сроки, отведённые ему историей; и это даёт нам право считать себя всё ещё в состоянии гражданской войны. Отсюда следует естественный вывод: если враг не сдаётся, - его истребляют.", Author = "Максим Горький" },
