            new Quote { Id = "https://ru.wikiquote.org/wiki/Максим_Горький", Text = "Ложь - религия рабов и хозяев. Правда - бог свободного человека.", Author = "Максим Горький" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Максим_Горький", Text = "Лучшее наслаждение, самая высокая радость жизни - чувствовать себя нужным и близким людям.", Author = "Максим Горький" },
