            new Quote { Id = "https://ru.wikiquote.org/wiki/Максим_Горький", Text = "Люди запутываются в массе лишних слов.", Author = "Максим Горький" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Максим_Горький", Text = "Нет силы более могучей, чем знание; человек, вооружённый знанием, - непобедим.", Author = "Максим Горький" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Максим_Горький", Text = "Память, этот бич несчастных, оживляет даже камни прошлого и даже в яд, выпитый некогда, подливает капли мёда...", Author = "Максим Горький" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Максим_Горький", Text = "Русские люди, по нищете и скудости жизни своей, вообще любят забавляться горем, играют им, как дети, и редко стыдятся быть несчастными. В бесконечных буднях и горе - праздник и пожар - забава; на пустом лице и царапина - украшение...", Author = "Максим Горький" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Максим_Горький", Text = "Слово - одежда всех фактов, всех мыслей.", Author = "Максим Горький" },
