            new Quote { Id = "https://ru.wikiquote.org/wiki/Максим_Горький", Text = "Ум имей хоть маленький, да свой.", Author = "Максим Горький" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Максим_Горький", Text = "Учитель, если он честен, всегда должен быть внимательным учеником.", Author = "Максим Горький" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Максим_Горький", Text = "Чтобы иметь право критиковать - надо верить в какую-то истину.", Author = "Максим Горький" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Максим_Горький", Text = "Человек - чудо, единственное чудо на земле, а все остальные чудеса её - результаты творчества его воли, разума, воображения.", Author = "Максим Горький" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Максим_Горький", Text = "Язык - это оружие литератора, как ружьё - солдата. Чем лучше оружие - тем сильнее воин...", Author = "Максим Горький" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Максим_Горький", Text = "Я не могу идеализировать, я только уверен, что все люди могут быть очень хорошими людьми, если они хотят этого и имеют на это свободное время. (\"Горемыка Павел\", 1894)", Author = "Максим Горький" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Максим_Горький", Text = "Господи! Сколько на земле всякой сволочи, совершенно не нужной никому, совершенно ни на что не способной, тупой, скучаю­щей от пустоты своей, жадной на всё новое, глупо жадной.", Author = "Максим Горький" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Максим_Горький", Text = "Русский человек всегда ищет хозяина, кто бы командовал им извне, а ежели он пере­рос это рабье стремление, так ищет хомута, который надевает себе изнутри на душу, стремясь опять-таки не дать свободы ни уму, ни сердцу.", Author = "Максим Горький" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Максим_Горький", Text = "Надо понять, что труд учёного - достояние всего человечества, а наука является областью наибольшего бескорыстия.", Author = "Максим Горький" },
